-- ==============================================================================
-- DPSjur - Script de Correção Complementar Pós-Importação (Fase 1 -> VPS)
-- Banco Alvo: "dpsjur" (PostgreSQL 16.6 no EasyPanel/VPS)
-- Data: 2026-10-06
-- ==============================================================================
-- Este script corrige as 3 divergências apontadas pela conferência pós-importação:
--   1. Remove as 550 tarefas duplicadas geradas acidentalmente pelo trigger on_case_created
--   2. Restaura o histórico completo de public.user_sessions (3.718 registros)
--   3. Restaura public.backup_logs e public.backup_export_config
-- ==============================================================================

SET statement_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

-- ==============================================================================
-- PARTE 1: LIMPEZA DAS TAREFAS-FANTASMA DUPLICADAS (TRIGGER on_case_created)
-- ==============================================================================
-- Durante a carga dos 550 cases, o trigger on_case_created disparou e criou
-- 1 tarefa "Acompanhamento processual mensal" para cada processo.
-- Identificação segura: título EXATO e created_at a partir de 2026-02-01 (data da carga no VPS).

-- 1.a) Bloco de conferência: contagem das tarefas que serão apagadas
DO $$
DECLARE
    v_count INT;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM public.tasks
    WHERE title = 'Acompanhamento processual mensal'
      AND created_at >= '2026-02-01'::timestamptz;
    RAISE NOTICE '>>> Tarefas-fantasma encontradas para exclusão: % (Esperado: 550)', v_count;
END $$;

-- 1.b) Exclusão segura das tarefas duplicadas da importação
DELETE FROM public.tasks
WHERE title = 'Acompanhamento processual mensal'
  AND created_at >= '2026-02-01'::timestamptz;

